SELECT 
FROM ams_appointment a
WHERE a.store_id = #{storeId}
AND a.status NOT IN (3, 4)
AND a.start_time < #{endTime}
AND a.end_time > #{startTime}

SELECT 
    ,

FROM ams_appointment a
LEFT JOIN sys_user u ON a.customer_id = u.id
WHERE a.customer_id = #{customerId}

    AND a.start_time >= #{startDate}


    AND a.start_time <= #{endDate}


    AND a.status = #{status}

ORDER BY a.start_time DESC

SELECT 
    ,

FROM ams_appointment a
LEFT JOIN sys_user u ON a.customer_id = u.id


        AND a.store_id = #{storeId}


        AND a.start_time >= #{startDate}


        AND a.start_time <= #{endDate}


        AND a.status = #{status}


        AND (
            a.contact_name LIKE CONCAT('%', #{keyword}, '%')
            OR a.contact_phone LIKE CONCAT('%', #{keyword}, '%')
            OR u.nickname LIKE CONCAT('%', #{keyword}, '%')
            OR u.username LIKE CONCAT('%', #{keyword}, '%')
        )


ORDER BY a.start_time DESC

