SELECT DATE_FORMAT(start_time, '%Y-%m-%d') as date, COUNT(*) as count
FROM ams_appointment
WHERE store_id = #{storeId}
AND start_time BETWEEN #{start} AND #{end}
GROUP BY DATE_FORMAT(start_time, '%Y-%m-%d')
